var SERVICE_CODES_KEY="savedServiceCodes",SERVICE_CODES_MAX=50;function migrateServiceCodes(e){var r=!1;return{data:e.map(function(e){return"string"==typeof e?(r=!0,{code:e,settings:null}):e}),migrated:r}}function getSavedServiceCodes(){try{var e=localStorage.getItem(SERVICE_CODES_KEY);if(!e)return[];var r=JSON.parse(e);if(!Array.isArray(r))return[];var t=migrateServiceCodes(r);return t.migrated&&localStorage.setItem(SERVICE_CODES_KEY,JSON.stringify(t.data)),t.data}catch(e){return[]}}function getServiceCodeNames(){return getSavedServiceCodes().map(function(e){return e.code})}function saveServiceCode(e,r){if(e&&"string"==typeof e&&(e=e.trim())){var t=getSavedServiceCodes();(t=t.filter(function(r){return r.code!==e})).unshift({code:e,settings:r||null}),t.length>SERVICE_CODES_MAX&&(t=t.slice(0,SERVICE_CODES_MAX)),localStorage.setItem(SERVICE_CODES_KEY,JSON.stringify(t))}}function getServiceCodeSettings(e){for(var r=getSavedServiceCodes(),t=0;t<r.length;t++)if(r[t].code===e)return r[t].settings;return null}function deleteServiceCode(e){var r=getSavedServiceCodes();r=r.filter(function(r){return r.code!==e}),localStorage.setItem(SERVICE_CODES_KEY,JSON.stringify(r))}function exportServiceCodes(){var e=getSavedServiceCodes();return JSON.stringify({version:1,exportedAt:(new Date).toISOString(),serviceCodes:e},null,2)}function importServiceCodes(e){var r=JSON.parse(e);if(!r||!Array.isArray(r.serviceCodes))throw new Error("Invalid import format");for(var t=migrateServiceCodes(r.serviceCodes).data,i=getSavedServiceCodes(),n=[],o={},S=0;S<t.length;S++)n.push(t[S]),o[t[S].code]=!0;for(S=0;S<i.length;S++)o[i[S].code]||n.push(i[S]);return n.length>SERVICE_CODES_MAX&&(n=n.slice(0,SERVICE_CODES_MAX)),localStorage.setItem(SERVICE_CODES_KEY,JSON.stringify(n)),{imported:t.length,total:n.length}}